{g:14,lv:2,q:"Payqa ____.",s:"Él/ella está durmiendo.",ans:"puñuchkanmi",opts:["puñuchkanmi","puñuchkani","puñuchkanki","puñuchkanku"],note:"puñu-chka-n-mi = está durmiendo + -mi afirmación · pay = él/ella · -n = 3ª persona"},
{g:14,lv:2,q:"Paykunaqa quchapim ____.",s:"Ellos están nadando en la piscina.",ans:"tuytuchkanku",opts:["tuytuchkanku","tuytuchkani","tuytuchkan","tuytuchkankichik"],note:"tuytu-chka-nku = están nadando · -nku = 3ª plural · qucha = piscina/lago"},
{g:14,lv:2,q:"Ñuqaqa ____.",s:"Estoy descansando.",ans:"samachkanim",opts:["samachkanim","puñuchkanim","mikuchkanim","pukllachkanim"],note:"samachkanim = estoy descansando · -m al final = evidencia directa · sama = descansar"},
{g:14,lv:2,q:"Maríaqa ____.",s:"María está comiendo.",ans:"mikuchkanmi",opts:["mikuchkanmi","mikuchkani","mikuchkanki","mikuchkanku"],note:"miku-chka-n-mi = está comiendo · -mi evidencia directa · mikuy = comer"},
{g:14,lv:2,q:"Ñuqaqa ____.",s:"Estoy cosiendo.",ans:"sirachkani",opts:["sirachkani","samachkani","puñuchkani","tuytuchkani"],note:"siray = coser · sirachkani = estoy cosiendo · sirachkani ≠ samachkani (descansando)"},
{g:14,lv:2,q:"Waynakunaqa chakrapim ____.",s:"Los jóvenes están trabajando en el campo.",ans:"llamkachkankum",opts:["llamkachkankum","llamkachkani","llamkachkan","llamkachkanki"],note:"llamka-chka-nku-m = están trabajando · puriy = caminar · wayna = joven · chakra = campo"},
{g:14,lv:3,q:"¿Imatataq taytanchik ____?",s:"¿Qué está haciendo nuestro papá?",ans:"rurachkan",opts:["rurachkan","rurachkanki","rurachkani","rurachkanku"],note:"rurachkan = él/ella está haciendo · taytanchik = nuestro papá (-nchik = nuestro inclusivo)"},
{g:14,lv:3,q:"Paykunaqa yanupim ____.",s:"Ellos están cocinando.",ans:"yanuchkanku",opts:["yanuchkanku","yanuchkani","yanuchkan","yanuchkanki"],note:"yanuy = cocinar · yanu-chka-nku = están cocinando · -ku = 3ª persona plural"},

// ─── GRUPO 15 · R2 Lección 3 · Verbos transitivos y cocina ──────────
{g:15,lv:3,q:"Robertoqa runtutam ____.",s:"Él está friendo huevos.",ans:"tiqtichkan",opts:["tiqtichkan","pasichkan","kanchachkan","kutachkan"],note:"tiqtiy = freír (en aceite) · runtu = huevo · -ta = sufijo de objeto directo · tiqtichkan = está friendo"},
{g:15,lv:3,q:"Almaqa chuñutam ____.",s:"Ella está cociendo chuño.",ans:"pasichkan",opts:["pasichkan","tiqtichkan","kanchachkan","hamkachkan"],note:"pasiy = cocer en agua · chuño = papa deshidratada andina · pasichkan = está cociendo"},
{g:15,lv:3,q:"Ladyqa quwitam ____.",s:"Lady está asando cuy.",ans:"kanchachkan",opts:["kanchachkan","tiqtichkan","pasichkan","kutachkan"],note:"kankay = asar (directo al fuego) · quwi = cuy · kanchachkan = está asando"},
{g:15,lv:3,q:"Felipeqa maranpi saratam ____.",s:"Felipe está moliendo maíz en el batán.",ans:"kutachkan",opts:["kutachkan","tiqtichkan","pasichkan","kanchachkan"],note:"kutay = moler · maran = batán (piedra para moler) · sara = maíz · -pi locativo"},
{g:15,lv:3,q:"Juanaqa yakutam ____.",s:"Juana está bebiendo agua.",ans:"upyachkan",opts:["upyachkan","mikuchkan","yanuchkan","pasichkan"],note:"upyay = beber · yaku = agua · upya-chka-n = está bebiendo"},
{g:15,lv:3,q:"Ñuqaqa chuñutam ____.",s:"Estoy tostando chuño.",ans:"hamkachkani",opts:["hamkachkani","pasichkani","kutachkani","tiqtichkani"],note:"hamkay = tostar en seco · chuño hamkay = tostar chuño · -ni = 1ª persona singular"},
{g:15,lv:3,q:"Payqa maranpi sarata____ kutachkan.",s:"Él está moliendo el maíz.",ans:"m",opts:["m","ta","pi","wan"],note:"-ta/-tam = objeto directo + evidencia · saratam kutachkan = está moliendo EL maíz"},
{g:15,lv:3,q:"Payqa runtutam ____.",s:"Él está friendo huevos.",ans:"tiqtichkan",opts:["tiqtichkan","pasichkan","watyachkan","kanchachkan"],note:"tiqtiy = freír (aceite) · watyay = hornear (horno tierra) · kankay = asar (fuego directo)"},
{g:15,lv:3,q:"Ñuqaqa tantata ____.",s:"Estoy horneando pan.",ans:"watyachkani",opts:["watyachkani","tiqtichkani","pasichkani","kutachkani"],note:"watyay = hornear · tanta = pan · watyachkani = estoy horneando"},
{g:15,lv:3,q:"¿Imatataq ____?",s:"¿Qué está haciendo él?",ans:"rurachkan",opts:["rurachkan","rurachkani","rurachkanki","rurachkanku"],note:"rurachkan = él/ella está haciendo · -kan = 3ª persona + prog · ruraqy = hacer/elaborar"},

// ─── GRUPO 16 · Ubicación espacial simple (5-6 palabras) ──────────────
{g:16,lv:3,q:"Inti ____ k'ancharishanchik.",s:"El sol brilla arriba de nosotros.",ans:"hawapi",opts:["hawapi","uraypi","qhepapi","ñawpaqpi"],note:"hawapi = arriba · k'ancha-ri-sha-nchik = está brillando sobre nosotros · hawa = parte de arriba/exterior"},
{g:16,lv:3,q:"Yaku ____ rijch'akun.",s:"El agua fluye por abajo.",ans:"uraypi",opts:["uraypi","hawapi","qhepapi","patapipi"],note:"uray = abajo · rijch'a-ku-n = fluye/corre · yaku = agua · uray-pi = en el lugar de abajo"},
{g:16,lv:3,q:"Urqu ____ wayra sinchita phukin.",s:"En la cima de la montaña el viento sopla fuerte.",ans:"patapipi",opts:["patapipi","uqhunpi","uraypi","qhepapi"],note:"pata-pi-pi = en la cima (doble locativo enfático) · wayra = viento · phu-ki-n = sopla · sinchita = fuerte"},
{g:16,lv:3,q:"Chay sach'a ____ tiyakushani.",s:"Estoy descansando detrás de ese árbol.",ans:"qhepapi",opts:["qhepapi","ñawpaqpi","hawapi","uraypi"],note:"sach'a = árbol · qhepa-pi = detrás · tiyaku-sha-ni = estoy sentado/descansando"},
{g:16,lv:3,q:"Wasi ____ warmikuna llamk'ashankus.",s:"Delante de la casa las mujeres trabajan.",ans:"ñawpaqpi",opts:["ñawpaqpi","qhepapi","uqhunpi","uraypi"],note:"ñawpaq-pi = delante de · warmi-kuna = mujeres · llamk'a-sha-nku-s = están trabajando (reportativo)"},
{g:16,lv:3,q:"Nuqa wasiyman ____ yaykunisaq.",s:"Entraré adentro de mi casa.",ans:"uqhunman",opts:["uqhunman","hawaman","qhepaman","pataninman"],note:"uqhu-n-man = hacia adentro · yayku-ni-saq = entraré (futuro 1sg) · wasi-y-man = a mi casa"},
{g:16,lv:3,q:"Kay qaypimanta Inti ____ urqumanta lloqsimun.",s:"Desde acá el sol sale desde detrás de la montaña.",ans:"qhepanmanta",opts:["qhepanmanta","pataninmanta","hawanmanta","urayninmanta"],note:"qaypimanta = desde acá · qhepa-n-manta = desde detrás · lloqsimu-n = sale (viniendo acá) · urqu-manta = de la montaña"},
{g:16,lv:3,q:"Paykuna urqu ____ sumaq panoramata rikushankus.",s:"Ellos están viendo un hermoso panorama desde la cima.",ans:"pataninpi",opts:["pataninpi","uqhunpi","urayninpi","qhepanpi"],note:"urqu pata-nin-pi = en la cima de la montaña · sumaq panorama-ta = el hermoso panorama · riku-sha-nku-s = están viendo"},

// ─── GRUPO 17 · Ubicación con movimiento (6-8 palabras) ───────────────
{g:17,lv:3,q:"Nuqa urquman ____ siqisaq allinta.",s:"Subiré hacia arriba de la montaña con cuidado.",ans:"hawaman",opts:["hawaman","uraman","qhepaman","ñawpaqman"],note:"hawa-man = hacia arriba · siqi-saq = subiré (futuro 1sg) · urqu-man = hacia la montaña · allinta = bien/con cuidado"},
{g:17,lv:3,q:"Wayra ____ hamun chiri apamushatin.",s:"El viento viene de abajo trayendo frío.",ans:"urayninmanta",opts:["urayninmanta","hawanmanta","qhepanmanta","ñawpaqninmanta"],note:"uray-nin-manta = desde abajo · chiri apamu-sha-tin = trayendo frío (simultáneo) · wayra = viento"},
{g:17,lv:4,q:"Pacha yaku urqumanta ____ pasashamin.",s:"La lluvia cae desde detrás de la montaña.",ans:"qhepanmanta",opts:["qhepanmanta","hawanmanta","uqhunmanta","ñawpaqninmanta"],note:"pacha yaku = lluvia (agua del cielo) · qhepa-n-manta = desde detrás de ella · pasa-sha-mi-n = cae/pasa"},
{g:17,lv:4,q:"Nuqa wasiyman ____ yaykurqani tullurqani.",s:"Entré adentro de la casa cansado.",ans:"uqhunman",opts:["uqhunman","hawaman","qhepaman","pataninman"],note:"uqhu-n-man = hacia adentro · yayku-rqa-ni = entré (pasado) · tullu-rqa-ni = estaba cansado"},
{g:17,lv:4,q:"Wawakuna urqu ____ laqt'akamushankus.",s:"Los niños están bajando desde la cima de la montaña.",ans:"pataninmanta",opts:["pataninmanta","uqhunmanta","ñawpaqninmanta","qhepanmanta"],note:"urqu pata-nin-manta = desde la cima de la montaña · laqt'a-ka-mu-sha-nku-s = están bajando acá"},
{g:17,lv:4,q:"Apu sinchi saminchawanchik urqu ____.",s:"El Apu nos bendice poderosamente desde la cima de la montaña.",ans:"pataninmanta",opts:["pataninmanta","uqhunmanta","urayninmanta","qhepanmanta"],note:"Apu = espíritu de la montaña · samincha-wa-nchik = nos bendice · urqu pata-nin-manta = desde la cima de la montaña"},
{g:17,lv:4,q:"Nuqa sach'a ____ pakaykushani mana rikurinaypaq.",s:"Me estoy escondiendo detrás del árbol para no aparecer.",ans:"qhepanpi",opts:["qhepanpi","ñawpaqninpi","hawanpi","uqhunpi"],note:"qhepa-n-pi = detrás de él · pakayku-sha-ni = me estoy escondiendo · mana rikuri-na-y-paq = para no aparecer"},
{g:17,lv:4,q:"Chay punku ____ pitaq kachkan nispa tapurqani.",s:"Pregunté quién estaba detrás de esa puerta.",ans:"qhepanpichu",opts:["qhepanpichu","ñawpaqninpichu","hawanpichu","uqhunpichu"],note:"punku = puerta · qhepa-n-pi-chu = ¿detrás de ella? · pi-taq = ¿quién? · tapurqani = pregunté"},

// ─── GRUPO 18 · Contexto espiritual con dirección (8-10 palabras) ─────
{g:18,lv:4,q:"Pachamama ____ kawsanchik, paypa sunqunpi tiykanchik.",s:"Vivimos dentro de la Pachamama, existimos en su corazón.",ans:"uqhunpi",opts:["uqhunpi","hawanpi","qhepanpi","pataninpi"],note:"Pachamama uqhu-n-pi = dentro de la Pachamama · sunqu-n-pi = en su corazón · tiyaka-nchik = existimos"},
{g:18,lv:4,q:"Inti urqumanta ____ lloqsimushan sumaqta k'ancharimushatin.",s:"El sol está saliendo desde detrás de la montaña brillando hermosamente.",ans:"qhepanmanta",opts:["qhepanmanta","pataninmanta","uqhunmanta","urayninmanta"],note:"lloqsimu-sha-n = está saliendo (acá) · qhepa-n-manta = desde detrás · k'ancha-ri-mu-sha-tin = brillando al venir"},
{g:18,lv:5,q:"Kay allpapi kawsashanchik, Pachamama ____ tiyanchik kallpaninwan.",s:"Vivimos en esta tierra, existimos dentro de la Pachamama con su fuerza.",ans:"uqhunpi",opts:["uqhunpi","hawanpi","ñawpaqninpi","qhepanpi"],note:"allpa-pi = en la tierra · kawsasha-nchik = vivimos · uqhu-n-pi = dentro de ella · kallpa-nin-wan = con su fuerza"},
{g:18,lv:5,q:"Apu urqu ____ sinchi wayra phukin kawsayta yachachiwanchik.",s:"Desde la cima del Apu sopla viento fuerte enseñándonos a vivir.",ans:"pataninmanta",opts:["pataninmanta","uqhunmanta","urayninmanta","qhepanmanta"],note:"Apu urqu pata-nin-manta = desde la cima del Apu · phu-ki-n = sopla · kawsay-ta yacha-chi-wa-nchik = nos enseña a vivir"},
{g:18,lv:5,q:"Ñawpaq machulakuna urqu ____ kawsarqankus chaypi kawsayninku kachkan.",s:"Nuestros ancestros vivieron en la cima, allí vive su espíritu.",ans:"pataninpi",opts:["pataninpi","uqhunpi","urayninpi","qhepanpi"],note:"ñawpaq machu-la-kuna = ancestros de antes · urqu pata-nin-pi = en la cima · kawsay-nin-ku = su manera de vivir"},
{g:18,lv:5,q:"Kay wayra urqu ____ hamun, Apup saminninmi.",s:"Este viento viene desde detrás de esa montaña, es la bendición del Apu.",ans:"qhepanmanta",opts:["qhepanmanta","pataninmanta","uqhunmanta","ñawpaqninmanta"],note:"wayra = viento · urqu qhepa-n-manta = desde detrás de la montaña · hamu-n = viene · Apu-p sami-n-ni-m = es la bendición del Apu"},
{g:18,lv:5,q:"Nuqa tukuy sunquywan Pachamama ____ yupaychani kay allpapi kawsaspa.",s:"Con todo mi corazón honro a la Pachamama desde lo más profundo viviendo en esta tierra.",ans:"uqhunmanta",opts:["uqhunmanta","hawanmanta","qhepanmanta","pataninmanta"],note:"tukuy sunquy-wan = con todo mi corazón · uqhu-n-manta = desde adentro/lo profundo · yupaycha-ni = honro · allpa-pi kawsaspa = viviendo en esta tierra"},
{g:18,lv:5,q:"Chay wakacha urqu ____ lloqsimushan Apum kasqa nispa willawaran.",s:"Esa figura sagrada está saliendo desde la cima de la montaña, me dijeron que es el Apu.",ans:"pataninmanta",opts:["pataninmanta","uqhunmanta","urayninmanta","qhepanmanta"],note:"wakacha = figura sagrada/wak'a pequeña · urqu pata-nin-manta = desde la cima · Apu-m kasqa = resulta que es el Apu · willa-wara-n = me dijeron"}
